marker='megapolis-price-on-request-20261019'
by_file={}
for p in patches:by_file.setdefault(p['file'],[]).append(p)
before={};patched={}
for rel,edits in by_file.items():
 f=root/rel
 if not f.is_file():raise RuntimeError('Missing theme file '+rel)
 src=f.read_text(encoding='utf-8')
 if marker in src:raise RuntimeError('Already patched '+rel)
 before[rel]=src
 for e in edits:
  old=e['old'];num=src.count(old)
  if num!=e['expected']:raise RuntimeError('Preflight '+rel+' count '+str(num)+' instead of '+str(e['expected'])+' '+old[:90])
  if e.get('occurrence'):
   start=-1
   for i in range(e['occurrence']):
    start=src.find(old,start+1)
   src=src[:start]+e['replacement']+src[start+len(old):]
  else:src=src.replace(old,e['replacement'])
 patched[rel]=src
print('PRICE_REQUEST_PREFLIGHT='+json.dumps({'ok':True,'files':list(by_file),'edits':len(patches)}),flush=True)
backup=root.parent/'storefront-backups'/('on-request-'+datetime.datetime.utcnow().strftime('%Y%m%dT%H%M%SZ')+'-'+str(os.getpid()))
backup.mkdir(parents=True,mode=0o700)
for n,rel in enumerate(by_file):
 shutil.copy2(str(root/rel),str(backup/(str(n)+'.bak')));os.chmod(str(backup/(str(n)+'.bak')),0o600)
written=[]
